import test from 'node:test';
import assert from 'node:assert/strict';
import { overdueInvoices } from '../src/reports.js';
import { createInvoice } from '../src/invoices.js';
import { issueInvoice } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('overdueInvoices returns empty list when no invoices overdue', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1, discountPercent: 0 }],
    terms: 'NET30',
  });
  assert.equal(r.ok, true);
  const draft = r.value;

  const r2 = issueInvoice(draft, []);
  assert.equal(r2.ok, true);
  const issued = r2.value;

  // Due date is 2026-11-06, check as of 2026-10-31 (not overdue yet)
  const report = overdueInvoices([issued], '2026-10-31');
  assert.equal(report.length, 0);
});

test('overdueInvoices includes overdue invoices', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1, discountPercent: 0 }],
    terms: 'NET14',
  });
  assert.equal(r.ok, true);
  const draft = r.value;

  const r2 = issueInvoice(draft, []);
  assert.equal(r2.ok, true);
  const issued = r2.value;

  // Due date is 2026-10-21, check as of 2026-10-25 (4 days overdue)
  const report = overdueInvoices([issued], '2026-10-25');
  assert.equal(report.length, 1);
  assert.equal(report[0].number, 'INV-2026-0001');
  assert.equal(report[0].customerId, 'C-003');
  assert.equal(report[0].dueDate, '2026-10-21');
  assert.equal(report[0].daysOverdue, 4);
  assert.equal(report[0].due, 145200);
});

test('overdueInvoices excludes invoices not yet due', () => {
  const r1 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1, discountPercent: 0 }],
    terms: 'NET30',
  });
  assert.equal(r1.ok, true);
  const draft1 = r1.value;

  const r2 = issueInvoice(draft1, []);
  assert.equal(r2.ok, true);
  const issued1 = r2.value; // Due 2026-11-06

  const r3 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-10',
    lines: [{ sku: 'LOGO-PACK', qty: 1, discountPercent: 0 }],
    terms: 'NET14',
  });
  assert.equal(r3.ok, true);
  const draft2 = r3.value;

  const r4 = issueInvoice(draft2, ['INV-2026-0001']);
  assert.equal(r4.ok, true);
  const issued2 = r4.value; // Due 2026-10-24

  // Check as of 2026-10-22: second invoice not yet due, first not overdue
  const report = overdueInvoices([issued1, issued2], '2026-10-22');
  assert.equal(report.length, 0);
});

test('overdueInvoices excludes draft invoices', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1, discountPercent: 0 }],
    terms: 'NET14',
  });
  assert.equal(r.ok, true);
  const draft = r.value; // dueDate 2026-10-21

  const report = overdueInvoices([draft], '2026-10-25');
  assert.equal(report.length, 0);
});

test('overdueInvoices excludes paid invoices', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1, discountPercent: 0 }],
    terms: 'NET14',
  });
  assert.equal(r.ok, true);
  const draft = r.value;

  const r2 = issueInvoice(draft, []);
  assert.equal(r2.ok, true);
  let issued = r2.value;

  const r3 = recordPayment(issued, { amount: 145200, date: '2026-10-08' });
  assert.equal(r3.ok, true);
  const paid = r3.value;

  const report = overdueInvoices([paid], '2026-10-25');
  assert.equal(report.length, 0);
});

test('overdueInvoices includes partially_paid invoices', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1, discountPercent: 0 }],
    terms: 'NET14',
  });
  assert.equal(r.ok, true);
  const draft = r.value;

  const r2 = issueInvoice(draft, []);
  assert.equal(r2.ok, true);
  let issued = r2.value;

  const r3 = recordPayment(issued, { amount: 50000, date: '2026-10-08' });
  assert.equal(r3.ok, true);
  const partially = r3.value;

  const report = overdueInvoices([partially], '2026-10-25');
  assert.equal(report.length, 1);
  assert.equal(report[0].due, 95200);
});

test('overdueInvoices sorts by most overdue first', () => {
  const r1 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-01',
    lines: [{ sku: 'LOGO-PACK', qty: 1, discountPercent: 0 }],
    terms: 'NET14',
  });
  assert.equal(r1.ok, true);
  const draft1 = r1.value;

  const r2 = issueInvoice(draft1, []);
  assert.equal(r2.ok, true);
  const issued1 = r2.value; // Due 2026-10-15

  const r3 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-10',
    lines: [{ sku: 'LOGO-PACK', qty: 1, discountPercent: 0 }],
    terms: 'NET14',
  });
  assert.equal(r3.ok, true);
  const draft2 = r3.value;

  const r4 = issueInvoice(draft2, ['INV-2026-0001']);
  assert.equal(r4.ok, true);
  const issued2 = r4.value; // Due 2026-10-24

  // Check as of 2026-10-31: both overdue
  const report = overdueInvoices([issued2, issued1], '2026-10-31');
  assert.equal(report.length, 2);
  assert.equal(report[0].number, 'INV-2026-0001'); // 16 days overdue (due 2026-10-15)
  assert.equal(report[0].daysOverdue, 16);
  assert.equal(report[1].number, 'INV-2026-0002'); // 7 days overdue (due 2026-10-24)
  assert.equal(report[1].daysOverdue, 7);
});

test('overdueInvoices calculates daysOverdue correctly', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1, discountPercent: 0 }],
    terms: 'NET14',
  });
  assert.equal(r.ok, true);
  const draft = r.value;

  const r2 = issueInvoice(draft, []);
  assert.equal(r2.ok, true);
  const issued = r2.value; // Due 2026-10-21

  // Check 10 days after due date
  const report = overdueInvoices([issued], '2026-10-31');
  assert.equal(report[0].daysOverdue, 10);
});

test('overdueInvoices handles multiple customers', () => {
  const r1 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1, discountPercent: 0 }],
    terms: 'NET14',
  });
  assert.equal(r1.ok, true);
  const draft1 = r1.value;

  const r2 = issueInvoice(draft1, []);
  assert.equal(r2.ok, true);
  const issued1 = r2.value; // C-003, due 2026-10-21

  const r3 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-05',
    lines: [{ sku: 'LOGO-PACK', qty: 1, discountPercent: 0 }],
    terms: 'NET14',
  });
  assert.equal(r3.ok, true);
  const draft2 = r3.value;

  const r4 = issueInvoice(draft2, ['INV-2026-0001']);
  assert.equal(r4.ok, true);
  const issued2 = r4.value; // C-001, due 2026-10-19

  const report = overdueInvoices([issued1, issued2], '2026-10-25');
  assert.equal(report.length, 2);
  assert.equal(report[0].customerId, 'C-001'); // More overdue (6 days vs 4 days)
  assert.equal(report[1].customerId, 'C-003');
});

test('overdueInvoices with exact due date is not overdue', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1, discountPercent: 0 }],
    terms: 'NET14',
  });
  assert.equal(r.ok, true);
  const draft = r.value;

  const r2 = issueInvoice(draft, []);
  assert.equal(r2.ok, true);
  const issued = r2.value; // Due 2026-10-21

  // Check on due date (not overdue)
  const report = overdueInvoices([issued], '2026-10-21');
  assert.equal(report.length, 0);
});

test('overdueInvoices day after due date is overdue', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1, discountPercent: 0 }],
    terms: 'NET14',
  });
  assert.equal(r.ok, true);
  const draft = r.value;

  const r2 = issueInvoice(draft, []);
  assert.equal(r2.ok, true);
  const issued = r2.value; // Due 2026-10-21

  // Check one day after due date (1 day overdue)
  const report = overdueInvoices([issued], '2026-10-22');
  assert.equal(report.length, 1);
  assert.equal(report[0].daysOverdue, 1);
});

test('overdueInvoices preserves all invoice details', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1, discountPercent: 0 }],
    terms: 'NET14',
  });
  assert.equal(r.ok, true);
  const draft = r.value;

  const r2 = issueInvoice(draft, []);
  assert.equal(r2.ok, true);
  const issued = r2.value;

  const report = overdueInvoices([issued], '2026-10-25');
  assert.equal(report.length, 1);
