  assert.equal(r3.ok, true);
  const paid = r3.value;

  const report = overdueInvoices([paid], '2026-10-25');
  assert.equal(report.length, 0);
});

test('overdueInvoices includes partially_paid invoices', () => {
  const r = createInvoice({
