test('vatSummary aggregates across multiple invoices', () => {
  const r1 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2, discountPercent: 0 }],
  });
  assert.equal(r1.ok, true);
  const draft1 = r1.value;

  const r2 = issueInvoice(draft1, []);
  assert.equal(r2.ok, true);
  const issued1 = r2.value;

  const r3 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-08',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
  });
  assert.equal(r3.ok, true);
  const draft2 = r3.value;

  const r4 = issueInvoice(draft2, ['INV-2026-0001']);
  assert.equal(r4.ok, true);
  const issued2 = r4.value;

  const report = vatSummary([issued1, issued2]);
  // 3 DES-HOUR at 8500 cents each = 25500 base
  assert.equal(report.length, 1);
  assert.equal(report[0].rate, 21);
  assert.equal(report[0].base, 25500);
  // 25500 * 21% = 5355 cents
  assert.equal(report[0].vat, 5355);
});

test('vatSummary handles zero VAT rate', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'TALK', qty: 1, discountPercent: 0 }],
  });
  assert.equal(r.ok, true);
  const draft = r.value;

  const r2 = issueInvoice(draft, []);
  assert.equal(r2.ok, true);
  const issued = r2.value;

  const report = vatSummary([issued]);
  assert.equal(report.length, 1);
  assert.equal(report[0].rate, 0);
  assert.equal(report[0].base, 35000);
  assert.equal(report[0].vat, 0);
});

test('vatSummary does not mutate input', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
  });
  assert.equal(r.ok, true);
  const draft = r.value;

  const r2 = issueInvoice(draft, []);
  assert.equal(r2.ok, true);
  const issued = r2.value;

  const before = JSON.stringify(issued);
  vatSummary([issued]);
  const after = JSON.stringify(issued);

  assert.equal(before, after);
});

