import { invoiceTotals, lineTotal, lineDiscount, lineVat } from './invoices.js';
import { balanceDue } from './payments.js';
import { daysBetween } from './dates.js';
import { roundCents } from './money.js';

/**
 * Find overdue invoices as of a given date.
 * @param {Array<any>} invoices - All invoices
 * @param {string} asOf - Date in YYYY-MM-DD format (cutoff date)
 * @returns {Array<{ number: string, customerId: string, dueDate: string, daysOverdue: number, due: number }>} - Sorted most overdue first
 */
export function overdueInvoices(invoices, asOf) {
  return invoices
    .filter((inv) => inv.status === 'issued' || inv.status === 'partially_paid')
    .filter((inv) => inv.dueDate && inv.dueDate < asOf)
    .map((inv) => ({
      number: inv.number,
      customerId: inv.customerId,
      dueDate: inv.dueDate,
      daysOverdue: daysBetween(inv.dueDate, asOf),
      due: balanceDue(inv),
    }))
    .sort((a, b) => b.daysOverdue - a.daysOverdue);
}

/**
 * Summarize VAT by rate across finalized invoices.
 * @param {Array<any>} invoices - All invoices
 * @returns {Array<{ rate: number, base: number, vat: number }>} - Sorted by rate descending
 */
export function vatSummary(invoices) {
  const summary = {};

  invoices
    .filter((inv) => inv.status === 'issued' || inv.status === 'partially_paid' || inv.status === 'paid')
    .forEach((inv) => {
      inv.lines.forEach((line) => {
        const rate = line.vatRate;
        const base = roundCents(lineTotal(line) - lineDiscount(line));
        const vat = lineVat(line);

        if (!summary[rate]) {
          summary[rate] = { base: 0, vat: 0 };
        }
        summary[rate].base = roundCents(summary[rate].base + base);
        summary[rate].vat = roundCents(summary[rate].vat + vat);
      });
    });

  return Object.entries(summary)
    .map(([rate, { base, vat }]) => ({
      rate: parseFloat(rate),
      base,
      vat,
    }))
    .sort((a, b) => b.rate - a.rate);
}
